+        return enabled;
+    }
+
+    public MetricGroup getMetricGroup() {
+        return metricGroup;
+    }
+
+    public int getHistorySize() {
+        return historySize;
+    }
+
+    public int getSampleInterval() {
+        return sampleInterval;
+    }
+
+    public boolean isStateNameAsVariable() {
+        return stateNameAsVariable;
+    }
+
