+            this.stateNameAsVariable = stateNameAsVariable;
+            return (B) this;
+        }
+
+        public B setMetricGroup(MetricGroup metricGroup) {
+            this.metricGroup = metricGroup;
+            return (B) this;
+        }
+
+        public abstract T build();
+    }
+}

