+                                    assertThat(path.getFileSystem().exists(path)).isTrue();
+                                } catch (IOException e) {
+                                    throw new RuntimeException(e);
+                                }
+                            });
+        }
+    }
+
+    static class FileNameGenerator {
+        int sstFileCount = 0;
+        int miscFileCount = 0;
+
+        FileNameGenerator() {}
+
+        String genSSTFile() {
+            return String.format("sst-%d.sst", sstFileCount++);
+        }
+
+        String genMiscFile() {
+            return String.format("misc-%d", miscFileCount++);
+        }
