-                int day = rand.nextInt(27) + 1; // day between 1 and 28
-
-                // IP address
-                StringBuilder visit =
-                        new StringBuilder(
-                                rand.nextInt(256)
-                                        + "."
-                                        + rand.nextInt(256)
-                                        + "."
-                                        + rand.nextInt(256)
-                                        + "."
-                                        + rand.nextInt(256)
-                                        + "|");
