-            new Tuple5<>(10, 100L, "HelloWorld", 200L, 20);
-    private final Tuple5<Integer, Long, String, Long, Integer> smaller =
-            new Tuple5<>(5, 50L, "Hello", 50L, 15);
-
-    // Special case where only the last value determines if bigger or smaller
