-        assertThat(iteration.getParallelism()).isEqualTo(iterationParallelism);
-    }
-
-    // --------------------------------------------------------------------------------------------
-
-    private static class IdentityMapper<T> extends RichMapFunction<T, T> {
-        @Override
-        public T map(T value) throws Exception {
-            return value;
-        }
-    }
-}

