-     */
-    private double[] transferFromListToArrayWithOrder(List<Double> list) {
-        Collections.sort(list);
-        double[] result = new double[list.size()];
-        for (int i = 0; i < list.size(); i++) {
-            result[i] = list.get(i);
-        }
-        return result;
-    }
