-                                    lProps,
-                                    initialInput));
-        }
-    }
-
-    public BulkPartialSolutionPlanNode getCurrentPartialSolutionPlanNode() {
-        if (this.cachedPlans != null) {
-            return (BulkPartialSolutionPlanNode) this.cachedPlans.get(0);
