- * <p>During the enumeration of interesting properties, this connection also holds all interesting
- * properties generated by the successor operator.
- */
-public class DagConnection implements EstimateProvider, DumpableConnection<OptimizerNode> {
-
-    private final OptimizerNode source; // The source node of the connection
-
-    private final OptimizerNode target; // The target node of the connection.
-
-    private final ExecutionMode
-            dataExchangeMode; // defines whether to use batch or pipelined data exchange
-
-    private InterestingProperties
-            interestingProps; // local properties that succeeding nodes are interested in
-
-    private ShipStrategyType shipStrategy; // The data shipping strategy, if predefined.
-
-    private TempMode materializationMode = TempMode.NONE; // the materialization mode
-
-    private int maxDepth = -1;
-
-    private boolean
-            breakPipeline; // whether this connection should break the pipeline due to potential
-    // deadlocks
-
-    /**
-     * Creates a new Connection between two nodes. The shipping strategy is by default
-     * <tt>null</tt>.
-     *
-     * @param source The source node.
-     * @param target The target node.
-     * @param exchangeMode The data exchange mode (pipelined / batch / batch only for shuffles / ...
-     *     )
-     */
-    public DagConnection(OptimizerNode source, OptimizerNode target, ExecutionMode exchangeMode) {
-        this(source, target, null, exchangeMode);
-    }
-
-    /**
-     * Creates a new Connection between two nodes.
-     *
-     * @param source The source node.
-     * @param target The target node.
-     * @param shipStrategy The shipping strategy.
-     * @param exchangeMode The data exchange mode (pipelined / batch / batch only for shuffles / ...
-     *     )
-     */
-    public DagConnection(
-            OptimizerNode source,
-            OptimizerNode target,
-            ShipStrategyType shipStrategy,
-            ExecutionMode exchangeMode) {
-        if (source == null || target == null) {
-            throw new NullPointerException("Source and target must not be null.");
-        }
-        this.source = source;
-        this.target = target;
-        this.shipStrategy = shipStrategy;
-        this.dataExchangeMode = exchangeMode;
-    }
-
-    /**
-     * Constructor to create a result from an operator that is not consumed by another operator.
-     *
-     * @param source The source node.
-     * @param exchangeMode The data exchange mode (pipelined / batch / batch only for shuffles / ...
-     *     )
-     */
-    public DagConnection(OptimizerNode source, ExecutionMode exchangeMode) {
-        if (source == null) {
-            throw new NullPointerException("Source must not be null.");
-        }
-        this.source = source;
-        this.target = null;
-        this.shipStrategy = ShipStrategyType.NONE;
-        this.dataExchangeMode = exchangeMode;
-    }
-
-    /**
-     * Gets the source of the connection.
