-        // cost and prune the plans
-        for (PlanNode node : outputPlans) {
-            estimator.costOperator(node);
-        }
-        prunePlanAlternatives(outputPlans);
-        outputPlans.trimToSize();
-
-        this.cachedPlans = outputPlans;
-        return outputPlans;
