-
-    protected void addLocalCandidates(
-            Channel template1,
-            Channel template2,
-            List<Set<? extends NamedChannel>> broadcastPlanChannels,
-            RequestedGlobalProperties rgps1,
-            RequestedGlobalProperties rgps2,
-            List<PlanNode> target,
-            LocalPropertiesPair[] validLocalCombinations,
-            CostEstimator estimator) {
-        for (RequestedLocalProperties ilp1 :
-                this.input1.getInterestingProperties().getLocalProperties()) {
-            final Channel in1 = template1.clone();
-            ilp1.parameterizeChannel(in1);
-
-            for (RequestedLocalProperties ilp2 :
-                    this.input2.getInterestingProperties().getLocalProperties()) {
-                final Channel in2 = template2.clone();
-                ilp2.parameterizeChannel(in2);
-
-                for (OperatorDescriptorDual dps : getProperties()) {
-                    for (LocalPropertiesPair lpp : dps.getPossibleLocalProperties()) {
-                        if (lpp.getProperties1().isMetBy(in1.getLocalProperties())
-                                && lpp.getProperties2().isMetBy(in2.getLocalProperties())) {
-                            // valid combination
-                            // for non trivial local properties, we need to check that they are co
-                            // compatible
-                            // (such as when some sort order is requested, that both are the same
-                            // sort order
-                            if (dps.areCoFulfilled(
-                                    lpp.getProperties1(),
-                                    lpp.getProperties2(),
-                                    in1.getLocalProperties(),
-                                    in2.getLocalProperties())) {
-                                // copy, because setting required properties and instantiation may
-                                // change the channels and should not affect prior candidates
-                                Channel in1Copy = in1.clone();
-                                in1Copy.setRequiredLocalProps(lpp.getProperties1());
-
-                                Channel in2Copy = in2.clone();
-                                in2Copy.setRequiredLocalProps(lpp.getProperties2());
-
-                                // all right, co compatible
-                                instantiate(
-                                        dps,
-                                        in1Copy,
-                                        in2Copy,
-                                        broadcastPlanChannels,
-                                        target,
-                                        estimator,
-                                        rgps1,
-                                        rgps2,
-                                        ilp1,
-                                        ilp2);
-                                break;
-                            }
-                            // else cannot use this pair, fall through the loop and try the next one
-                        }
-                    }
-                }
-            }
-        }
-    }
-
-    protected void instantiate(
-            OperatorDescriptorDual operator,
-            Channel in1,
-            Channel in2,
-            List<Set<? extends NamedChannel>> broadcastPlanChannels,
-            List<PlanNode> target,
-            CostEstimator estimator,
-            RequestedGlobalProperties globPropsReq1,
-            RequestedGlobalProperties globPropsReq2,
-            RequestedLocalProperties locPropsReq1,
-            RequestedLocalProperties locPropsReq2) {
-        final PlanNode inputSource1 = in1.getSource();
-        final PlanNode inputSource2 = in2.getSource();
-
-        for (List<NamedChannel> broadcastChannelsCombination :
-                Sets.cartesianProduct(broadcastPlanChannels)) {
-
-            boolean validCombination = true;
-
-            // check whether the broadcast inputs use the same plan candidate at the branching point
-            for (int i = 0; i < broadcastChannelsCombination.size(); i++) {
-                NamedChannel nc = broadcastChannelsCombination.get(i);
-                PlanNode bcSource = nc.getSource();
-
-                if (!(areBranchCompatible(bcSource, inputSource1)
-                        || areBranchCompatible(bcSource, inputSource2))) {
-                    validCombination = false;
-                    break;
-                }
-
-                // check branch compatibility against all other broadcast variables
-                for (int k = 0; k < i; k++) {
-                    PlanNode otherBcSource = broadcastChannelsCombination.get(k).getSource();
-
-                    if (!areBranchCompatible(bcSource, otherBcSource)) {
-                        validCombination = false;
-                        break;
-                    }
-                }
-            }
-
-            if (!validCombination) {
-                continue;
-            }
-
-            placePipelineBreakersIfNecessary(operator.getStrategy(), in1, in2);
-
-            DualInputPlanNode node = operator.instantiate(in1, in2, this);
-            node.setBroadcastInputs(broadcastChannelsCombination);
-
-            SemanticProperties semPropsGlobalPropFiltering =
-                    getSemanticPropertiesForGlobalPropertyFiltering();
-            GlobalProperties gp1 =
-                    in1.getGlobalProperties()
-                            .clone()
-                            .filterBySemanticProperties(semPropsGlobalPropFiltering, 0);
-            GlobalProperties gp2 =
-                    in2.getGlobalProperties()
-                            .clone()
-                            .filterBySemanticProperties(semPropsGlobalPropFiltering, 1);
-            GlobalProperties combined = operator.computeGlobalProperties(gp1, gp2);
-
-            SemanticProperties semPropsLocalPropFiltering =
-                    getSemanticPropertiesForLocalPropertyFiltering();
-            LocalProperties lp1 =
-                    in1.getLocalProperties()
-                            .clone()
-                            .filterBySemanticProperties(semPropsLocalPropFiltering, 0);
-            LocalProperties lp2 =
-                    in2.getLocalProperties()
-                            .clone()
-                            .filterBySemanticProperties(semPropsLocalPropFiltering, 1);
-            LocalProperties locals = operator.computeLocalProperties(lp1, lp2);
-
-            node.initProperties(combined, locals);
-            node.updatePropertiesWithUniqueSets(getUniqueFields());
-            target.add(node);
-        }
-    }
-
-    protected void placePipelineBreakersIfNecessary(
-            DriverStrategy strategy, Channel in1, Channel in2) {
-        // before we instantiate, check for deadlocks by tracing back to the open branches and
-        // checking
-        // whether either no input, or all of them have a dam
-        if (in1.isOnDynamicPath()
-                && in2.isOnDynamicPath()
-                && this.hereJoinedBranches != null
-                && this.hereJoinedBranches.size() > 0) {
-            boolean someDamOnLeftPaths = false;
-            boolean damOnAllLeftPaths = true;
-            boolean someDamOnRightPaths = false;
-            boolean damOnAllRightPaths = true;
-
-            if (strategy.firstDam() == DamBehavior.FULL_DAM
-                    || in1.getLocalStrategy().dams()
-                    || in1.getTempMode().breaksPipeline()) {
-                someDamOnLeftPaths = true;
-            } else {
-                for (OptimizerNode brancher : this.hereJoinedBranches) {
-                    PlanNode candAtBrancher = in1.getSource().getCandidateAtBranchPoint(brancher);
-
-                    // not all candidates are found, because this list includes joined branched from
-                    // both regular inputs and broadcast vars
-                    if (candAtBrancher == null) {
-                        continue;
-                    }
-
-                    SourceAndDamReport res = in1.getSource().hasDamOnPathDownTo(candAtBrancher);
-                    if (res == NOT_FOUND) {
-                        throw new CompilerException(
-                                "Bug: Tracing dams for deadlock detection is broken.");
-                    } else if (res == FOUND_SOURCE) {
-                        damOnAllLeftPaths = false;
-                    } else if (res == FOUND_SOURCE_AND_DAM) {
-                        someDamOnLeftPaths = true;
-                    } else {
-                        throw new CompilerException();
-                    }
-                }
-            }
-
-            if (strategy.secondDam() == DamBehavior.FULL_DAM
-                    || in2.getLocalStrategy().dams()
-                    || in2.getTempMode().breaksPipeline()) {
-                someDamOnRightPaths = true;
-            } else {
-                for (OptimizerNode brancher : this.hereJoinedBranches) {
-                    PlanNode candAtBrancher = in2.getSource().getCandidateAtBranchPoint(brancher);
-
-                    // not all candidates are found, because this list includes joined branched from
-                    // both regular inputs and broadcast vars
-                    if (candAtBrancher == null) {
-                        continue;
-                    }
-
-                    SourceAndDamReport res = in2.getSource().hasDamOnPathDownTo(candAtBrancher);
-                    if (res == NOT_FOUND) {
-                        throw new CompilerException(
-                                "Bug: Tracing dams for deadlock detection is broken.");
-                    } else if (res == FOUND_SOURCE) {
-                        damOnAllRightPaths = false;
-                    } else if (res == FOUND_SOURCE_AND_DAM) {
-                        someDamOnRightPaths = true;
-                    } else {
-                        throw new CompilerException();
-                    }
-                }
-            }
-
-            // okay combinations are both all dam or both no dam
-            if ((damOnAllLeftPaths && damOnAllRightPaths)
-                    || (!someDamOnLeftPaths && !someDamOnRightPaths)) {
-                // good, either both materialize already on the way, or both fully pipeline
-            } else {
-                if (someDamOnLeftPaths && !damOnAllRightPaths) {
-                    // right needs a pipeline breaker
-                    in2.setTempMode(in2.getTempMode().makePipelineBreaker());
-                }
-
-                if (someDamOnRightPaths && !damOnAllLeftPaths) {
-                    // right needs a pipeline breaker
-                    in1.setTempMode(in1.getTempMode().makePipelineBreaker());
-                }
-            }
-        }
-    }
-
-    @Override
-    public void computeUnclosedBranchStack() {
-        if (this.openBranches != null) {
-            return;
-        }
-
-        // handle the data flow branching for the regular inputs
-        addClosedBranches(getFirstPredecessorNode().closedBranchingNodes);
-        addClosedBranches(getSecondPredecessorNode().closedBranchingNodes);
-
-        List<UnclosedBranchDescriptor> result1 =
-                getFirstPredecessorNode().getBranchesForParent(getFirstIncomingConnection());
-        List<UnclosedBranchDescriptor> result2 =
-                getSecondPredecessorNode().getBranchesForParent(getSecondIncomingConnection());
-
-        ArrayList<UnclosedBranchDescriptor> inputsMerged =
-                new ArrayList<UnclosedBranchDescriptor>();
-        mergeLists(result1, result2, inputsMerged, true);
-
-        // handle the data flow branching for the broadcast inputs
-        List<UnclosedBranchDescriptor> result =
-                computeUnclosedBranchStackForBroadcastInputs(inputsMerged);
-
-        this.openBranches =
-                (result == null || result.isEmpty())
-                        ? Collections.<UnclosedBranchDescriptor>emptyList()
-                        : result;
-    }
-
-    @Override
-    public SemanticProperties getSemanticProperties() {
-        return getOperator().getSemanticProperties();
-    }
-
-    protected SemanticProperties getSemanticPropertiesForLocalPropertyFiltering() {
-        return this.getSemanticProperties();
-    }
-
-    protected SemanticProperties getSemanticPropertiesForGlobalPropertyFiltering() {
-        return this.getSemanticProperties();
-    }
-
-    // --------------------------------------------------------------------------------------------
-    //                                     Miscellaneous
-    // --------------------------------------------------------------------------------------------
-
-    @Override
-    public void accept(Visitor<OptimizerNode> visitor) {
-        if (visitor.preVisit(this)) {
-            if (this.input1 == null || this.input2 == null) {
-                throw new CompilerException();
-            }
-
-            getFirstPredecessorNode().accept(visitor);
-            getSecondPredecessorNode().accept(visitor);
-
-            for (DagConnection connection : getBroadcastConnections()) {
-                connection.getSource().accept(visitor);
-            }
-
-            visitor.postVisit(this);
-        }
-    }
-}

