-    }
-
-    public LocalStrategy getLocalStrategy() {
-        return this.localStrategy;
-    }
-
-    public FieldList getLocalStrategyKeys() {
-        return this.localKeys;
-    }
-
-    public boolean[] getLocalStrategySortOrder() {
