-                return FOUND_SOURCE;
-            }
-        } else {
-            SourceAndDamReport res2 = this.input2.getSource().hasDamOnPathDownTo(source);
-            if (res2 == FOUND_SOURCE_AND_DAM) {
-                return FOUND_SOURCE_AND_DAM;
