-                // NOT_FOUND
-                // check the broadcast inputs
-
-                for (NamedChannel nc : getBroadcastInputs()) {
-                    SourceAndDamReport bcRes = nc.getSource().hasDamOnPathDownTo(source);
-                    if (bcRes != NOT_FOUND) {
