-                    // adjust the driver
-                    if (conf.getDriver().equals(JoinDriver.class)) {
-                        conf.setDriver(
-                                inputNum == 0
-                                        ? JoinWithSolutionSetFirstDriver.class
-                                        : JoinWithSolutionSetSecondDriver.class);
-                    } else if (conf.getDriver().equals(CoGroupDriver.class)) {
-                        conf.setDriver(
-                                inputNum == 0
