-                // make sure we do not visit this node again. for that, we add a 'already seen'
-                // entry into one of the sets
-                this.chainedTasks.put(node, ALREADY_VISITED_PLACEHOLDER);
-
-                vertex = null;
-            } else if (node instanceof WorksetPlanNode) {
