-                    && node.getOutgoingChannels().size() > 0) {
-                WorksetIterationPlanNode wspn = (WorksetIterationPlanNode) this.currentIteration;
-                if (wspn.getSolutionSetDeltaPlanNode() == pred
-                        || wspn.getNextWorkSetPlanNode() == pred) {
-                    chaining = false;
-                }
-            }
