-            iter.getNextWorkset().accept(recursiveCreator);
-
-            SolutionSetNode solutionSetNode =
-                    (SolutionSetNode) recursiveCreator.con2node.get(iter.getSolutionSet());
-
-            if (solutionSetNode == null
