-                    || solutionSetNode.getOutgoingConnections().isEmpty()) {
-                solutionSetNode =
-                        new SolutionSetNode(
-                                (DeltaIterationBase.SolutionSetPlaceHolder<?>)
-                                        iter.getSolutionSet(),
-                                iterNode);
-            } else {
