-    private int getPosInFieldList(int field, FieldList list) {
-
-        int pos;
-        for (pos = 0; pos < list.size(); pos++) {
-            if (field == list.get(pos)) {
-                break;
-            }
-        }
-        if (pos == list.size()) {
-            return -1;
-        } else {
-            return pos;
-        }
-    }
