-            env.setParallelism(parallelism);
-
-            DataSet<Tuple2<Long, Long>> initialSolutionSet = env.fromCollection(verticesInput);
-            DataSet<Tuple2<Long, Long>> edges = env.fromCollection(edgesInput);
-            int keyPosition = 0;
