-            DeltaIteration<Tuple2<Long, Long>, Tuple2<Long, Long>> iteration =
-                    initialSolutionSet.iterateDelta(
-                            initialSolutionSet, MAX_ITERATIONS, keyPosition);
-
-            DataSet<Long> candidates =
-                    iteration
-                            .getWorkset()
-                            .join(edges)
-                            .where(0)
-                            .equalTo(0)
-                            .with(new FindCandidatesJoin())
-                            .groupBy(
