-                Assert.assertEquals(superstep - 1, previousAggr.getValue());
-            }
-        }
-
-        @Override
-        public Tuple2<Integer, Integer> map(Tuple2<Integer, Integer> value) {
-            // count the ones
-            if (value.f1 == 1) {
-                aggr.aggregate(1L);
-            }
-            value.f1--;
-            return value;
-        }
-    }
-}

