-
-        private int broadcast;
-
-        @Override
-        public void open(OpenContext openContext) {
-            Collection<Integer> ints = this.getRuntimeContext().getBroadcastVariable("ints");
-            int sum = 0;
-            for (Integer i : ints) {
-                sum += i;
-            }
-            broadcast = sum;
