-
-    private void checkPlan(OptimizedPlan plan) {
-
-        OptimizerPlanNodeResolver or = getOptimizerPlanNodeResolver(plan);
-
-        final SinkPlanNode sink = or.getNode(SINK);
-        final SingleInputPlanNode reducer = or.getNode(REDUCER_NAME);
