-    public static Plan kmeans(String[] args) throws Exception {
-        ExecutionEnvironment env = ExecutionEnvironment.getExecutionEnvironment();
-
-        DataSet<Point> points =
-                env.readCsvFile(args[0])
-                        .fieldDelimiter(" ")
-                        .includeFields(true, true)
-                        .types(Double.class, Double.class)
-                        .name(DATAPOINTS)
-                        .map(
-                                new MapFunction<Tuple2<Double, Double>, Point>() {
-                                    @Override
-                                    public Point map(Tuple2<Double, Double> value)
-                                            throws Exception {
-                                        return new Point(value.f0, value.f1);
-                                    }
-                                });
-
-        DataSet<Centroid> centroids =
-                env.readCsvFile(args[1])
-                        .fieldDelimiter(" ")
-                        .includeFields(true, true, true)
-                        .types(Integer.class, Double.class, Double.class)
-                        .name(CENTERS)
-                        .map(
