-                                    }
-                                });
-
-        DataSet<Tuple3<Integer, Point, Integer>> newCentroids =
-                points.map(new SelectNearestCenter())
-                        .name(MAPPER_NAME)
-                        .withBroadcastSet(centroids, "centroids");
