-    /** Two-dimensional point. */
-    public static class Point extends Tuple2<Double, Double> {
-        public Point(double x, double y) {
-            this.f0 = x;
-            this.f1 = y;
-        }
-
-        public Point add(Point other) {
-            f0 += other.f0;
-            f1 += other.f1;
-            return this;
-        }
-
-        public Point div(long val) {
-            f0 /= val;
-            f1 /= val;
-            return this;
-        }
-
-        public double euclideanDistance(Point other) {
-            return Math.sqrt((f0 - other.f0) * (f0 - other.f0) + (f1 - other.f1) * (f1 - other.f1));
-        }
-
-        public double euclideanDistance(Centroid other) {
-            return Math.sqrt(
-                    (f0 - other.f1.f0) * (f0 - other.f1.f0)
-                            + (f1 - other.f1.f1) * (f1 - other.f1.f1));
-        }
-    }
-
-    /** Center of a cluster. */
