-        DataSet<Point> points =
-                env.readCsvFile(args[0])
-                        .fieldDelimiter(" ")
-                        .includeFields(true, true)
-                        .types(Double.class, Double.class)
-                        .name(DATAPOINTS)
-                        .map(
-                                new MapFunction<Tuple2<Double, Double>, Point>() {
-                                    @Override
