-    /** Two-dimensional point. */
-    public static class Point extends Tuple2<Double, Double> {
-        public Point(double x, double y) {
-            this.f0 = x;
-            this.f1 = y;
-        }
-
-        public Point add(Point other) {
-            f0 += other.f0;
-            f1 += other.f1;
-            return this;
-        }
-
-        public Point div(long val) {
-            f0 /= val;
-            f1 /= val;
-            return this;
-        }
-
-        public double euclideanDistance(Point other) {
-            return Math.sqrt((f0 - other.f0) * (f0 - other.f0) + (f1 - other.f1) * (f1 - other.f1));
-        }
-
-        public double euclideanDistance(Centroid other) {
-            return Math.sqrt(
-                    (f0 - other.f1.f0) * (f0 - other.f1.f0)
-                            + (f1 - other.f1.f1) * (f1 - other.f1.f1));
-        }
-    }
-
-    /** Center of a cluster. */
-    public static class Centroid extends Tuple2<Integer, Point> {
-
-        public Centroid(int id, double x, double y) {
-            this.f0 = id;
-            this.f1 = new Point(x, y);
-        }
-
-        public Centroid(int id, Point p) {
-            this.f0 = id;
-            this.f1 = p;
-        }
-    }
-
-    /** Determines the closest cluster center for a data point. */
-    private static final class SelectNearestCenter
-            extends RichMapFunction<Point, Tuple3<Integer, Point, Integer>> {
-        private Collection<Centroid> centroids;
-
-        @Override
-        public void open(OpenContext openContext) throws Exception {
-            this.centroids = getRuntimeContext().getBroadcastVariable("centroids");
-        }
-
-        @Override
-        public Tuple3<Integer, Point, Integer> map(Point p) throws Exception {
-            double minDistance = Double.MAX_VALUE;
-            int closestCentroidId = -1;
-            for (Centroid centroid : centroids) {
-                double distance = p.euclideanDistance(centroid);
-                if (distance < minDistance) {
-                    minDistance = distance;
-                    closestCentroidId = centroid.f0;
-                }
-            }
-            return new Tuple3<>(closestCentroidId, p, 1);
-        }
-    }
-
-    private static final class RecomputeClusterCenter
-            implements GroupReduceFunction<
-                            Tuple3<Integer, Point, Integer>, Tuple3<Integer, Point, Integer>>,
-                    GroupCombineFunction<
-                            Tuple3<Integer, Point, Integer>, Tuple3<Integer, Point, Integer>> {
-
-        @Override
-        public void reduce(
-                Iterable<Tuple3<Integer, Point, Integer>> values,
-                Collector<Tuple3<Integer, Point, Integer>> out)
-                throws Exception {
-            int id = -1;
-            double x = 0;
-            double y = 0;
-            int count = 0;
-            for (Tuple3<Integer, Point, Integer> value : values) {
-                id = value.f0;
-                x += value.f1.f0;
-                y += value.f1.f1;
-                count += value.f2;
-            }
-            out.collect(new Tuple3<>(id, new Point(x, y), count));
-        }
-
-        @Override
-        public void combine(
-                Iterable<Tuple3<Integer, Point, Integer>> values,
-                Collector<Tuple3<Integer, Point, Integer>> out)
-                throws Exception {
-            reduce(values, out);
-        }
-    }
-}

