-        DataSet<Tuple2<Long, Long>> minAndUpdate =
-                joinWithNeighbors
-                        .coGroup(iteration.getSolutionSet())
-                        .where(0)
-                        .equalTo(0)
-                        .with(new DummyCoGroupFunction())
-                        .name(MIN_ID_AND_UPDATE);
-
-        iteration.closeWith(minAndUpdate, minAndUpdate).writeAsCsv(args[3]).name(SINK);
