-                            .join(adjacencyListInput)
-                            .where(0)
-                            .equalTo(0)
-                            .withParameters(cfg)
-                            .flatMap(new JoinVertexWithEdgesMatch())
-                            // collect and sum ranks
-                            .groupBy(0)
-                            .aggregate(SUM, 1)
