-
-            BulkPartialSolutionPlanNode partSolPlanNode = iterPlanNode.getPartialSolutionPlanNode();
-            Assert.assertEquals(
-                    ShipStrategyType.FORWARD,
-                    partSolPlanNode.getOutgoingChannels().get(0).getShipStrategy());
-        } catch (Exception e) {
-            e.printStackTrace();
-            fail(e.getMessage());
-        }
-    }
-}

