+
+    private static final Random RND = new Random();
+
+    private Collection<OperatorState> taskStates;
+
+    private CheckpointMetadata metadata;
+
+    @BeforeEach
+    public void beforeEach(@TempDir Path tempDir) throws IOException {
+        taskStates =
